340:   private buildOutgoingPointer(attachment: JsonMap): JsonMap {
341:     const pointer: JsonMap = jsonMap();
342:     const fields: string[] = Object.keys(attachment);
343:     for (let index = 0; index < fields.length; index++) {
344:       const field: string = fields[index];
345:       if (LOCAL_ONLY_FIELDS.indexOf(field) < 0) {
346:         pointer[field] = attachment[field];
347:       }
348:     }
349:     if (!isAudioAttachment(mapText(attachment, 'contentType'))) {
350:       return pointer;
351:     }
352:     const record: WaveformRecord | undefined = this.currentRecordFor(attachment);
353:     if (record === undefined || !record.isRenderable() || !(record.durationSeconds > 0)) {
354:       return pointer;
355:     }
356:     pointer['audioWaveform'] = this.magnitudesOf(record);
357:     pointer['audioDurationSeconds'] = record.durationSeconds;
358:     return pointer;
359:   }
360: 
361:   private describePointer(pointer: JsonMap, record: WaveformRecord | undefined): JsonMap {
362:     const described: JsonMap = jsonMap();
363:     const contentType: string = mapText(pointer, 'contentType');
364:     if (contentType.length > 0) {
365:       described['contentType'] = contentType;
366:     }
367:     const cdnKey: string = mapText(pointer, 'cdnKey');
368:     if (cdnKey.length > 0) {
369:       described['cdnKey'] = cdnKey;
370:     }
371:     if (record !== undefined) {
372:       described['barCount'] = record.barCount();
373:       described['audioWaveform'] = this.magnitudesOf(record);
374:       described['audioDurationSeconds'] = record.durationSeconds;
375:       described['senderProvided'] = record.isSenderProvided();
376:     }
377:     return described;
378:   }
