380:   private describeStaleRecord(record: WaveformRecord | undefined): string {
381:     if (record === undefined) {
382:       return 'waveform_absent';
383:     }
384:     if (record.isPlaceholder()) {
385:       return 'generation_placeholder';
386:     }
387:     if (record.isObsoleteGenerated()) {
388:       return 'obsolete_generated_bar_count';
389:     }
390:     return 'waveform_unusable';
391:   }
392: 
393:   private currentRecordFor(attachment: JsonMap): WaveformRecord | undefined {
394:     const attachmentId: string = mapText(attachment, 'id');
395:     if (this.record !== undefined && this.record.belongsTo(attachmentId)) {
396:       return this.record;
397:     }
398:     const stored: Object | undefined = attachment['storedWaveform'];
399:     if (!isPresent(stored)) {
400:       return undefined;
401:     }
402:     return WaveformRecord.fromStored(attachmentId, stored);
403:   }
